    private var appVersion: String {
        let version = Bundle.main.object(forInfoDictionaryKey: "CFBundleShortVersionString") as? String ?? "–"
        let build = Bundle.main.object(forInfoDictionaryKey: "CFBundleVersion") as? String ?? "–"
        return "\(version) (\(build))"
    }

    /// Öffnet das Kalender-Abo (webcal): iOS fragt dann "Abonnieren?" und
    /// hält die gemerkten Konzerte im Kalender automatisch aktuell.
    @MainActor
    /// Nach der Anmeldung aus dem Profil: Ist das Onboarding des Kontos noch
    /// offen (neuer Apple-/Google-Account, vorher als Gast unterwegs), startet
    /// es bei "Persönliche Daten"; sonst gilt es lokal als erledigt.
    private func continueOnboardingIfNeeded() async {
        guard let userRepository, let userID = auth.userID, let token = auth.accessToken else {
            didCompleteOnboarding = true
            return
        }
        if await OnboardingView.onboardingCompleted(repository: userRepository, userID: userID, token: token) {
            didCompleteOnboarding = true
        } else {
            // Erst nach dem Schließen des Login-Sheets präsentieren.
            try? await Task.sleep(for: .milliseconds(450))
            showsOnboardingAfterSignIn = true
        }
    }

    private func subscribeCalendar() async {
        guard let userRepository, let token = auth.accessToken,
              let feedToken = try? await userRepository.calendarFeedToken(token: token),
              let url = URL(string: "webcal://klangradar.com/api/calendar/\(feedToken).ics") else { return }
        await UIApplication.shared.open(url)
    }

    @MainActor
    private func deleteAccount() async {
        guard let userRepository, let token = auth.accessToken else { return }
        isDeletingAccount = true
        defer { isDeletingAccount = false }
        do {
            try await userRepository.deleteAccount(token: token)
            try? await auth.signOut()
        } catch {
            deleteAccountError = error.localizedDescription
        }
    }

    @MainActor
    private func checkEditorialAccess() async {
        guard let editorialRepository, let token = auth.accessToken, let userID = auth.userID else {
            hasEditorialAccess = false
            return
        }
        let cacheKey = "editorialAccess.\(userID.uuidString.lowercased())"
        if UserDefaults.standard.bool(forKey: cacheKey) {
            hasEditorialAccess = true
        }
        // Beim Wiederherstellen der Sitzung kann der erste Rollencheck noch
        // mit einem gerade erneuerten Token kollidieren. Kurze Wiederholungen
        // verhindern, dass der Redaktionsmodus dadurch komplett verschwindet.
        for attempt in 0..<3 {
            if await editorialRepository.hasAccess(token: token) {
                hasEditorialAccess = true
                UserDefaults.standard.set(true, forKey: cacheKey)
                return
            }
            if attempt < 2 { try? await Task.sleep(for: .milliseconds(450)) }
        }
    }


