                    }
        .navigationTitle("Einstellungen")
        .navigationBarTitleDisplayMode(.inline)
    }

    @ViewBuilder
    private var accountContent: some View {
        switch auth.state {
        case .unavailable:
            Label("Im Preview-Modus nicht verfügbar", systemImage: "person.crop.circle.badge.exclamationmark")
                .foregroundStyle(.secondary)
        case .loading:
            ProgressView("Sitzung wird vorbereitet …")
            Button("Anmelden", systemImage: "envelope") { showsLogin = true }
        case .anonymous:
            Button("Anmelden", systemImage: "envelope") {
                showsLogin = true
            }
        case let .authenticated(session):
            LabeledContent("Angemeldet als", value: session.user.email ?? "Klangradar Account")
            if BiometricAuth.availableBiometryKind != .none {
                Toggle(
                    BiometricAuth.availableBiometryKind == .faceID ? "Face ID zum Schutz nutzen" : "Touch ID zum Schutz nutzen",
                    isOn: Binding(
                        get: { biometricProtectionEnabled },
                        set: { enabled in
                            if enabled {
                                Task {
                                    if (try? await BiometricAuth.authenticate(reason: "Biometrischen Schutz für Klangradar aktivieren")) == true {
                                        biometricProtectionEnabled = true
                                    }
                                }
                            } else {
                                biometricProtectionEnabled = false
                            }
                        }
                    )
                )
            }
            NavigationLink("Blockierte Personen") { BlockedUsersView() }
            Button("Problem melden") { showsSupport = true }
                .sheet(isPresented: $showsSupport) { SupportSheet(auth: auth, repository: userRepository) }
            Button("Abmelden", role: .destructive) {
                Task { try? await auth.signOut() }
            }
            Button(isDeletingAccount ? "Konto wird gelöscht …" : "Konto löschen", role: .destructive) {
                showsDeleteAccountConfirmation = true
            }
            .disabled(isDeletingAccount)
            .confirmationDialog("Konto endgültig löschen?", isPresented: $showsDeleteAccountConfirmation, titleVisibility: .visible) {
                Button("Konto löschen", role: .destructive) { Task { await deleteAccount() } }
                Button("Abbrechen", role: .cancel) {}
            } message: {
                Text("Dein Konto, Favoriten, Listen, Konzerttagebuch, Chatnachrichten, Fotos und Einstellungen werden dauerhaft gelöscht. Ein Plus-Abo kündigst du separat in den Einstellungen deiner Apple-ID. Das kann nicht rückgängig gemacht werden.")
            }
            .alert("Konto konnte nicht gelöscht werden", isPresented: Binding(get: { deleteAccountError != nil }, set: { if !$0 { deleteAccountError = nil } })) {
                Button("OK", role: .cancel) {}
            } message: {
                Text(deleteAccountError ?? "")
            }
        case let .failed(message):
            Label(message, systemImage: "exclamationmark.triangle")
                .foregroundStyle(.red)
            Button("Erneut versuchen") {
                Task { await auth.bootstrap() }
            }
            Button("Anmelden", systemImage: "envelope") { showsLogin = true }
        }
    }
}

// Nutzerfeedback: "Design von 'Mein Klangradar' noch sehr durcheinander" --
// vorher reine Zahlen-Kacheln ohne Navigation, jede Kachel unterschiedlich
// hoch/breit wirkend. Jetzt: einheitliche, antippbare Zeilen-Kacheln (Icon +
// Wert + Chevron, dieselbe Sprache wie LevelDetailView.journeyValue), jede
// führt zu einer echten Liste mit funktionierender Weiternavigation.
struct MyKlangradarHubView: View {
    @ObservedObject var auth: AuthStore
    let repository: UserRepository?
    let eventRepository: any EventRepository
    let contentRepository: any ContentRepository
    @EnvironmentObject private var cityStore: CityStore
    @State private var stats: KlangradarStats?
    @State private var isLoading = false
    @State private var errorMessage: String?

    var body: some View {
        ScrollView {
            VStack(alignment: .leading, spacing: 22) {
                if let stats {
                    // Neu gestaltet (Nutzerwunsch 25.10.2026: "farblos, linear").
                    VStack(alignment: .leading, spacing: 14) {
                        Text("DEINE KLASSIKWELT").font(.caption.weight(.bold)).tracking(1.2).foregroundStyle(.white.opacity(0.8))
                        HStack(alignment: .lastTextBaseline, spacing: 0) {
                            heroNumber(stats.plannedEvents, "geplant")
                            heroNumber(stats.visitedEvents, "erlebt")
                            heroNumber(stats.savedEvents, "gemerkt")
                        }
                        Text(heroLine(stats)).font(.subheadline).foregroundStyle(.white.opacity(0.85))
                    }
                    .padding(20)
                    .frame(maxWidth: .infinity, alignment: .leading)
                    .background(KlangradarTheme.accent, in: .rect(cornerRadius: 24, style: .continuous))

                    Text("Deine Konzerte").font(.headline).padding(.top, 4)
                    HStack(spacing: 10) {
                        NavigationLink {
                            PlannedEventsListView(auth: auth, repository: repository, eventRepository: eventRepository, contentRepository: contentRepository)
                        } label: { tile("Geplant", stats.plannedEvents, "calendar.badge.checkmark", Color(red: 0.08, green: 0.38, blue: 0.58)) }
                        NavigationLink {
                            VisitedConcertsView(auth: auth, repository: repository, eventRepository: eventRepository, contentRepository: contentRepository)
                        } label: { tile("Besucht", stats.visitedEvents, "checkmark.seal.fill", Color(red: 0.16, green: 0.55, blue: 0.40)) }
                        NavigationLink {
                            FavoriteEventsView(auth: auth, repository: repository, eventRepository: eventRepository, contentRepository: contentRepository)
                        } label: { tile("Gemerkt", stats.savedEvents, "heart.fill", Color(red: 0.75, green: 0.25, blue: 0.32)) }
                    }
                    .buttonStyle(.plain)

                    HStack(spacing: 10) {
                        NavigationLink { SeasonPlannerView(repository: eventRepository) } label: {
                            plannerTile("Saisonplaner", "Deine nächsten Monate", "calendar.day.timeline.left", Color(red: 0.08, green: 0.38, blue: 0.58))
                        }
                        NavigationLink { ConcertDiaryListView() } label: {
                            plannerTile("Tagebuch", "Notizen & Fotos", "book.closed.fill", Color(red: 0.55, green: 0.35, blue: 0.20))
                        }
                    }
                    .buttonStyle(.plain)

                    MySubscriptionsSection(repository: eventRepository, contentRepository: contentRepository, cityID: cityStore.selectedCity?.id)

                    Text("Du folgst").font(.headline).padding(.top, 4)
                    LazyVGrid(columns: [.init(.flexible(), spacing: 10), .init(.flexible(), spacing: 10)], spacing: 10) {
                        NavigationLink {
                            FollowedPeopleView(auth: auth, repository: repository, contentRepository: contentRepository, filterKind: .person)
                        } label: { followRow("Personen", stats.followedPersons, "person.fill", Color(red: 0.42, green: 0.27, blue: 0.55)) }
                        NavigationLink {
                            FollowedPeopleView(auth: auth, repository: repository, contentRepository: contentRepository, filterKind: .ensemble)
                        } label: { followRow("Ensembles", stats.followedEnsembles, "person.3.fill", Color(red: 0.75, green: 0.45, blue: 0.20)) }
                        NavigationLink {
                            FollowedPeopleView(auth: auth, repository: repository, contentRepository: contentRepository, filterKind: .venue)
                        } label: { followRow("Orte", stats.followedVenues, "building.columns.fill", Color(red: 0.16, green: 0.50, blue: 0.55)) }
                        NavigationLink {
                            FollowedWorksListView(auth: auth, repository: repository, contentRepository: contentRepository)
                        } label: { followRow("Werke", stats.followedWorks, "music.note.list", Color(red: 0.55, green: 0.47, blue: 0.20)) }
                    }
                    .buttonStyle(.plain)
                } else if auth.accessToken == nil {
                    ContentUnavailableView("Anmeldung erforderlich", systemImage: "person.crop.circle.badge.exclamationmark")
                } else if let errorMessage {
                    ContentUnavailableView {
                        Label("Statistik nicht verfügbar", systemImage: "exclamationmark.triangle")
                    } description: {
                        Text(errorMessage)
                    } actions: {
                        Button("Erneut versuchen") { Task { await load() } }
                    }
                } else if isLoading {
                    ProgressView().frame(maxWidth: .infinity).padding()
                }
                Text("Interessen und Benachrichtigungen findest du direkt im Profil. Ein Konzert wird erst nach deiner Bestätigung als besucht gezählt.")
                    .font(.footnote).foregroundStyle(.secondary)
            }.padding()
        }
        // Nutzerfeedback: Kacheln hatten dieselbe Farbe wie der Hintergrund
        // (kein Kontrast sichtbar) -- gleiches Design wie Profil -> Level ->
        // "Meine Klangreise" (LevelDetailView): expliziter
        // .systemGroupedBackground-Seitenhintergrund, Kacheln in
        // .background (Systemvordergrund/Weiß) statt
        // .secondarySystemGroupedBackground (das dort fast identisch zum
        // Standard-Gruppenhintergrund aussieht).
        .background(Color(uiColor: .systemGroupedBackground))
        .navigationTitle("Mein Klangradar")
        .task { await load() }
    }

    private func plannerTile(_ title: String, _ subtitle: String, _ icon: String, _ color: Color) -> some View {
        HStack(spacing: 10) {
            Image(systemName: icon).font(.headline).foregroundStyle(.white)
                .frame(width: 38, height: 38).background(color, in: .rect(cornerRadius: 11, style: .continuous))
            VStack(alignment: .leading, spacing: 1) {
                Text(title).font(.subheadline.weight(.semibold)).foregroundStyle(.primary)
                Text(subtitle).font(.caption).foregroundStyle(.secondary).lineLimit(1)
            }
            Spacer(minLength: 0)
        }
        .padding(12)
        .frame(maxWidth: .infinity)
        .background(Color(uiColor: .systemBackground), in: .rect(cornerRadius: 16, style: .continuous))
    }

    private func heroNumber(_ value: Int, _ label: String) -> some View {
        VStack(alignment: .leading, spacing: 0) {
            Text(value.formatted()).font(.scaled(34, weight: .bold, design: .rounded)).monospacedDigit().foregroundStyle(.white)
            Text(label).font(.caption.weight(.semibold)).foregroundStyle(.white.opacity(0.8))
        }
        .frame(maxWidth: .infinity, alignment: .leading)
    }

    private func heroLine(_ stats: KlangradarStats) -> String {
        if stats.plannedEvents > 0 { return "Dein nächster Konzertabend wartet schon." }
        if stats.savedEvents > 0 { return "Aus deinen gemerkten Konzerten wird ein Abend – plane ihn." }
        return "Merke dir Konzerte mit ♡, dann füllt sich deine Klassikwelt."
    }

    private func tile(_ title: String, _ value: Int, _ icon: String, _ color: Color) -> some View {
        VStack(alignment: .leading, spacing: 10) {
            Image(systemName: icon)
                .font(.subheadline.weight(.semibold))
                .foregroundStyle(.white)
                .frame(width: 34, height: 34)
                .background(color, in: .circle)
            Spacer(minLength: 0)
            Text(value.formatted()).font(.title2.weight(.bold)).monospacedDigit()
            Text(title).font(.caption.weight(.semibold)).foregroundStyle(.secondary)
        }
        .padding(14)
        .frame(maxWidth: .infinity, minHeight: 124, alignment: .topLeading)
        .background(color.opacity(0.09), in: .rect(cornerRadius: 20, style: .continuous))
    }

    private func followRow(_ title: String, _ value: Int, _ icon: String, _ color: Color) -> some View {
        HStack(spacing: 10) {
            Image(systemName: icon)
                .font(.footnote.weight(.semibold))
                .foregroundStyle(color)
                .frame(width: 32, height: 32)
                .background(color.opacity(0.12), in: .rect(cornerRadius: 10, style: .continuous))
            VStack(alignment: .leading, spacing: 0) {
                Text(value.formatted()).font(.headline).monospacedDigit()
                Text(title).font(.caption).foregroundStyle(.secondary)
            }
            Spacer(minLength: 0)
            Image(systemName: "chevron.right").font(.caption2.bold()).foregroundStyle(.tertiary)
        }
        .padding(12)
        .background(Color(uiColor: .secondarySystemGroupedBackground), in: .rect(cornerRadius: 16, style: .continuous))
    }

    private func stat(_ title: String, _ value: Int, _ icon: String) -> some View {
        HStack(spacing: 10) {
            Image(systemName: icon).foregroundStyle(KlangradarTheme.accent).frame(width: 24)
            VStack(alignment: .leading, spacing: 1) { Text(value.formatted()).font(.title3.bold()).monospacedDigit(); Text(title).font(.caption).foregroundStyle(.secondary) }
            Spacer()
            Image(systemName: "chevron.right").font(.caption2.bold()).foregroundStyle(.tertiary)
        }.padding(13).background(.background, in: .rect(cornerRadius: 16, style: .continuous))
    }

    // Generated by Claude Code — RPC-Fehler zeigten vorher gar nichts an
    // (try? verschluckte sie), der Spinner drehte dadurch endlos weiter.
    @MainActor private func load() async {
        guard let repository, let token = auth.accessToken else { return }
        isLoading = true
        errorMessage = nil
        defer { isLoading = false }
        do {
            stats = try await repository.klangradarStats(token: token)
        } catch {
            errorMessage = error.localizedDescription
        }
    }
}


struct AccentColorSettingsView: View {
    private struct AccentOption: Identifiable {
        let name: String
        let hex: String
        var id: String { hex }
    }

    private static let suggestions: [AccentOption] = [
        .init(name: "Klangradar Blau", hex: "#146194"),
        .init(name: "Indigo", hex: "#5856D6"),
        .init(name: "Violett", hex: "#AF52DE"),
        .init(name: "Pink", hex: "#D94F70"),
        .init(name: "Orange", hex: "#D96B2B"),
        .init(name: "Grün", hex: "#248A5B"),
        .init(name: "Türkis", hex: "#008C95")
    ]

    @AppStorage(KlangradarTheme.accentStorageKey) private var storedHex = KlangradarTheme.defaultAccentHex
    @State private var draftHex: String
    @FocusState private var hexFieldFocused: Bool

    init() {
        let current = UserDefaults.standard.string(forKey: KlangradarTheme.accentStorageKey)
            ?? KlangradarTheme.defaultAccentHex
        _draftHex = State(initialValue: current)
    }

    private var normalizedDraft: String? { KlangradarTheme.normalizedHex(draftHex) }
    private var normalizedStored: String {
        KlangradarTheme.normalizedHex(storedHex) ?? KlangradarTheme.defaultAccentHex
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 14) {
            HStack {
                Label("Akzentfarbe", systemImage: "paintpalette.fill")
                Spacer()
                Circle()
                    .fill(KlangradarTheme.color(hex: normalizedStored) ?? KlangradarTheme.accent)
                    .frame(width: 22, height: 22)
                    .overlay { Circle().stroke(.white.opacity(0.8), lineWidth: 2) }
                    .shadow(color: .black.opacity(0.12), radius: 3, y: 1)
            }

            ScrollView(.horizontal, showsIndicators: false) {
                HStack(spacing: 13) {
                    ForEach(Self.suggestions) { option in
                        Button {
                            apply(option.hex)
                        } label: {
                            VStack(spacing: 6) {
                                ZStack {
                                    Circle()
                                        .fill(KlangradarTheme.color(hex: option.hex) ?? .clear)
                                        .frame(width: 38, height: 38)
                                    if normalizedStored == option.hex {
                                        Image(systemName: "checkmark")
                                            .font(.caption.bold())
                                            .foregroundStyle(.white)
                                    }
                                }
                                .overlay {
                                    Circle().stroke(
                                        normalizedStored == option.hex ? Color.primary.opacity(0.25) : Color.clear,
                                        lineWidth: 3
                                    ).padding(-3)
                                }
                                Text(option.name)
                                    .font(.scaled(10))
                                    .foregroundStyle(.secondary)
                                    .lineLimit(1)
                            }
                            .frame(width: 62)
                        }
                        .buttonStyle(.plain)
                        .accessibilityLabel(option.name)
                        .accessibilityValue(normalizedStored == option.hex ? "Ausgewählt" : "")
                    }
                }
                .padding(.horizontal, 3)
                .padding(.vertical, 4)
            }

            ColorPicker(
                "Farbe frei wählen",
                selection: Binding(
                    get: { KlangradarTheme.color(hex: normalizedStored) ?? KlangradarTheme.accent },
                    set: { color in
                        guard let hex = KlangradarTheme.hex(color: color) else { return }
                        apply(hex)
                    }
                ),
                supportsOpacity: false
            )

            VStack(alignment: .leading, spacing: 5) {
                Text("Eigener Hex-Code").font(.caption).foregroundStyle(.secondary)
                HStack(spacing: 8) {
                    TextField("#146194", text: $draftHex)
                        .font(.system(.body, design: .monospaced))
                        .textInputAutocapitalization(.characters)
                        .autocorrectionDisabled()
                        .keyboardType(.asciiCapable)
                        .submitLabel(.done)
                        .focused($hexFieldFocused)
                        .onSubmit { commitDraft() }
                    Button("Übernehmen") { commitDraft() }
                        .font(.subheadline.weight(.semibold))
                        .disabled(normalizedDraft == nil || normalizedDraft == normalizedStored)
                }
                if !draftHex.isEmpty, normalizedDraft == nil {
                    Text("Bitte sechs Hex-Zeichen eingeben, z. B. #146194.")
                        .font(.caption2).foregroundStyle(.red)
                } else {
                    Text("Die Farbe gilt sofort für Navigation, Buttons und Auswahlzustände.")
                        .font(.caption2).foregroundStyle(.secondary)
                }
            }
        }
        .padding(.vertical, 4)
        .onChange(of: storedHex) { _, newValue in
            guard !hexFieldFocused else { return }
            draftHex = KlangradarTheme.normalizedHex(newValue) ?? KlangradarTheme.defaultAccentHex
        }
    }

    private func commitDraft() {
        guard let normalizedDraft else { return }
        apply(normalizedDraft)
        hexFieldFocused = false
    }

    private func apply(_ hex: String) {
        guard let normalized = KlangradarTheme.normalizedHex(hex) else { return }
        withAnimation(.easeInOut(duration: 0.2)) {
            storedHex = normalized
            draftHex = normalized
        }
    }
}

struct ProfileOverview: View {
    @EnvironmentObject private var follows: FollowStore
    @ObservedObject var auth: AuthStore
    let repository: UserRepository?
    let usesPreviewData: Bool
    let onSelect: (ProfileDestination) -> Void
    @State private var profile: KlangradarUserProfile?
    @State private var socialSummary: ProfileSocialSummary = .empty
    @State private var friendCount = 0
    @ObservedObject private var plus = PlusStore.shared
    @State private var showsPlus = false

    var body: some View {
        VStack(spacing: 12) {
            ProfileAvatarEditor(auth: auth, repository: repository, size: 78)
                .overlay(alignment: .bottomTrailing) {
                    if plus.isPlus {
                        Button { showsPlus = true } label: {
                            Image(systemName: "diamond.fill")
                                .font(.scaled(12, weight: .bold))
                                .foregroundStyle(.white)
                                .frame(width: 26, height: 26)
                                .background(KlangradarTheme.accent, in: .circle)
                                .overlay(Circle().stroke(Color(uiColor: .systemBackground), lineWidth: 2.5))
                        }
                        .buttonStyle(.plain)
                        .offset(x: 2, y: 2)
                        .accessibilityLabel("Klangradar Plus aktiv")
                    }
                }
                .padding(.top, 4)

            VStack(spacing: 3) {
                HStack(spacing: 6) {
                    Text(displayName)
                        .font(.headline)
                    if plus.isPlus {
                        Button { showsPlus = true } label: {
                            Text("PLUS")
                                .font(.caption2.weight(.heavy)).tracking(0.8)
                                .foregroundStyle(KlangradarTheme.accent)
                                .padding(.horizontal, 7).padding(.vertical, 2)
                                .background(KlangradarTheme.accent.opacity(0.12), in: .capsule)
                        }
                        .buttonStyle(.plain)
                    }
                }
                Text(accountLine)
                    .font(.subheadline)
                    .foregroundStyle(.secondary)
                    .lineLimit(1)
            }

            HStack(spacing: 0) {
                Button { onSelect(.visits) } label: {
                    profileMetric(value: socialSummary.visitedConcerts, label: "Besuche")
                }
                // 06.11.2026: Freunde wie bei Instagram direkt unter dem Profilbild.
                if auth.userID != nil {
                    Divider().frame(height: 40)
                    Button { onSelect(.friends) } label: {
                        profileMetric(value: friendCount, label: "Freunde")
                    }
                }
                Divider().frame(height: 40)
                Button { onSelect(.follows) } label: {
                    profileMetric(value: followCount, label: "Gefolgt")
                }
                Divider().frame(height: 40)
                Button { onSelect(.level) } label: {
                    profileMetric(value: socialSummary.level, label: "Level")
                }
            }
            .buttonStyle(.plain)

            if auth.userID != nil {
                Button { onSelect(.edit) } label: {
                    Text("Profil bearbeiten")
                        .font(.subheadline.weight(.semibold))
                        .frame(maxWidth: .infinity)
                        .padding(.vertical, 5)
                }
                .buttonStyle(.bordered)
                .tint(KlangradarTheme.accent)
            }
        }
        .frame(maxWidth: .infinity)
        .padding(.horizontal, 14)
        .padding(.vertical, 6)
        .task(id: auth.userID) {
            // 07.11.2026: letzter Stand sofort, dann alles parallel nachladen.
            if let cached = ProfileSummaryCache.shared.cached(userID: auth.userID) { socialSummary = cached }
            if let id = auth.userID, let cached = Self.profileCache[id] { profile = cached }
            if let id = auth.userID, let cached = Self.friendCountCache[id] { friendCount = cached }
            await load()
        }
        .sheet(isPresented: $showsPlus) { PlusPaywallView() }
    }

    private func profileMetric(value: Int, label: String) -> some View {
        VStack(spacing: 3) {
            Text("\(value)").font(.title3.bold()).monospacedDigit()
            Text(label).font(.caption).foregroundStyle(.secondary)
                .frame(maxWidth: .infinity, alignment: .center)
        }
        .frame(maxWidth: .infinity)
        .contentShape(Rectangle())
        .accessibilityLabel("\(value) \(label)")
    }

    private var followCount: Int {
        follows.personIDs.count + follows.ensembleIDs.count + follows.venueIDs.count
    }

    private var displayName: String {
        if let name = profile?.displayName, !name.isEmpty { return name }
        if let email = auth.session?.user.email { return email.split(separator: "@").first.map(String.init) ?? email }
        return usesPreviewData ? "Preview-Profil" : "Dein Profil"
    }

    private var accountLine: String {
        auth.session?.user.email ?? (usesPreviewData ? "Preview-Modus" : "Noch nicht angemeldet")
    }

    private func load() async {
        guard let repository, let userID = auth.userID, let token = auth.accessToken else {
            profile = nil
            return
        }
        async let profileValue = try? repository.profile(userID: userID, token: token)
        async let summaryValue = repository.socialProfileSummary(userID: userID, token: token)
        async let friendsValue = try? repository.friends(token: token).count
        if let loaded = await profileValue { profile = loaded; Self.profileCache[userID] = loaded }
        socialSummary = await summaryValue
        if let count = await friendsValue { friendCount = count; Self.friendCountCache[userID] = count }
    }

    @MainActor private static var profileCache: [UUID: KlangradarUserProfile] = [:]
    @MainActor private static var friendCountCache: [UUID: Int] = [:]
}

struct AccountProfileEditView: View {
    @ObservedObject var auth: AuthStore
    let repository: UserRepository?
    @Environment(\.dismiss) private var dismiss

    @State private var displayName = ""
    @State private var birthDate = Date()
    @State private var hasBirthDate = false
    @State private var email = ""
    @State private var password = ""
    @State private var passwordConfirmation = ""
    @State private var isLoading = true
    @State private var isSaving = false
    @State private var message: String?
    @State private var errorMessage: String?

    var body: some View {
        Form {
            Section("Persönliche Angaben") {
                TextField("Name", text: $displayName)
                    .textContentType(.name)

                Toggle("Geburtstag hinterlegen", isOn: $hasBirthDate.animation())
                if hasBirthDate {
                    DatePicker(
                        "Geburtstag",
                        selection: $birthDate,
                        in: ...Date.now,
                        displayedComponents: .date
                    )
                }
            }

            Section("E-Mail-Adresse") {
                TextField("E-Mail-Adresse", text: $email)
                    .textContentType(.emailAddress)
                    .textInputAutocapitalization(.never)
                    .keyboardType(.emailAddress)
                Text("Nach einer Änderung sendet Supabase gegebenenfalls eine Bestätigung an die bisherige und die neue Adresse.")
                    .font(.footnote)
                    .foregroundStyle(.secondary)
            }

            Section("Neues Passwort") {
                SecureField("Mindestens 8 Zeichen", text: $password)
                    .textContentType(.newPassword)
                SecureField("Passwort wiederholen", text: $passwordConfirmation)
                    .textContentType(.newPassword)
                Text("Leer lassen, wenn das Passwort nicht geändert werden soll.")
                    .font(.footnote)
                    .foregroundStyle(.secondary)
            }

            if let message {
                Section { Label(message, systemImage: "checkmark.circle.fill").foregroundStyle(.green) }
            }
            if let errorMessage {
                Section { Label(errorMessage, systemImage: "exclamationmark.triangle.fill").foregroundStyle(.red) }
            }
        }
        .disabled(isLoading || isSaving)
        .overlay { if isLoading || isSaving { ProgressView() } }
        .navigationTitle("Profil bearbeiten")
        .navigationBarTitleDisplayMode(.inline)
        .toolbar {
            ToolbarItem(placement: .confirmationAction) {
                Button("Speichern") { Task { await save() } }
                    .disabled(displayName.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty)
            }
        }
        .task { await load() }
    }

    private func load() async {
        defer { isLoading = false }
        email = auth.session?.user.email ?? ""
        guard let repository, let userID = auth.userID, let token = auth.accessToken,
              let profile = try? await repository.profile(userID: userID, token: token) else { return }
        displayName = profile.displayName
        if let date = profile.birthDate {
            birthDate = date
            hasBirthDate = true
        }
    }

    private func save() async {
        errorMessage = nil
        message = nil
        let cleanEmail = email.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        guard cleanEmail.contains("@") else {
            errorMessage = "Bitte gib eine gültige E-Mail-Adresse ein."
            return
        }
        if !password.isEmpty {
            guard password.count >= 8 else {
                errorMessage = "Das neue Passwort muss mindestens 8 Zeichen lang sein."
                return
            }
            guard password == passwordConfirmation else {
                errorMessage = "Die eingegebenen Passwörter stimmen nicht überein."
                return
            }
        }

        guard let repository, let userID = auth.userID, let token = auth.accessToken else { return }
        isSaving = true
        defer { isSaving = false }
        do {
            try await repository.updateProfile(
                displayName: displayName,
                birthDate: hasBirthDate ? birthDate : nil,
                userID: userID,
                token: token
            )
            if cleanEmail != auth.session?.user.email?.lowercased() {
                try await auth.updateEmail(cleanEmail)
            }
            if !password.isEmpty {
                try await auth.updatePassword(password)
                password = ""
                passwordConfirmation = ""
            }
            message = "Deine Änderungen wurden gespeichert."
        } catch {
            errorMessage = error.localizedDescription
        }
    }
}

struct HomeCategoryOrderView: View {
    let userID: UUID?
    @State private var categories: [HomeRecommendationCategory]

    init(userID: UUID?) {
        self.userID = userID
        _categories = State(initialValue: HomeCategoryPreferences.order(for: userID))
    }

    var body: some View {
        List {
            Section {
                ForEach(categories) { category in
                    Label(category.title, systemImage: category.symbol)
                }
                .onMove(perform: move)
            } header: {
                Text("Reihenfolge")
            } footer: {
                Text("Halte eine Kategorie am Griff rechts fest und verschiebe sie nach oben oder unten. Die Titelveranstaltung bleibt immer an erster Stelle.")
            }

            Section {
                Button("Standardreihenfolge wiederherstellen", systemImage: "arrow.counterclockwise") {
                    HomeCategoryPreferences.reset(for: userID)
                    categories = HomeRecommendationCategory.defaultOrder
                }
            }
        }
        .navigationTitle("Homepage anordnen")
        .navigationBarTitleDisplayMode(.inline)
        .environment(\.editMode, .constant(.active))
        .onAppear {
            categories = HomeCategoryPreferences.order(for: userID)
        }
        .onDisappear {
            // Zusätzlich zum sofortigen Speichern nach jedem Drag: schützt
            // vor einem SwiftUI-Neuaufbau während der Move-Animation.
            HomeCategoryPreferences.save(categories, for: userID)
        }
    }

    private func move(from source: IndexSet, to destination: Int) {
        categories.move(fromOffsets: source, toOffset: destination)
        HomeCategoryPreferences.save(categories, for: userID)
    }
}


